import{Ct as e,Et as t,Tt as n,kt as r}from"./app-p182cZ-5.js";var i=JSON.parse(`{"path":"/07-%E5%9B%9E%E5%BD%92%E6%A8%A1%E5%9E%8B%E4%B8%8E%E4%B8%9A%E5%8A%A1%E8%A7%A3%E9%87%8A.html","title":"Week 7 回归模型与业务解释","lang":"zh-CN","frontmatter":{"description":"Week 7 回归模型与业务解释 本章导读 时长：3 节课，每节 45 分钟 数据：data/07-modeling/BostonHousing.csv 参考脚本：scripts/07-regression/ 下 4 个文件，与正文代码块一一对应。 你将学到：建立第一个线性回归模型，用 MAE、RMSE、R² 评估误差，解释系数方向、相关性与共线性，最...","head":[["script",{"type":"application/ld+json"},"{\\"@context\\":\\"https://schema.org\\",\\"@type\\":\\"Article\\",\\"headline\\":\\"Week 7 回归模型与业务解释\\",\\"image\\":[\\"\\"],\\"dateModified\\":null,\\"author\\":[]}"],["meta",{"property":"og:url","content":"https://zhouxianzhong.cn/courses/python-data-analysis/07-%E5%9B%9E%E5%BD%92%E6%A8%A1%E5%9E%8B%E4%B8%8E%E4%B8%9A%E5%8A%A1%E8%A7%A3%E9%87%8A.html"}],["meta",{"property":"og:site_name","content":"Vibe Programming × Python 数据分析"}],["meta",{"property":"og:title","content":"Week 7 回归模型与业务解释"}],["meta",{"property":"og:description","content":"Week 7 回归模型与业务解释 本章导读 时长：3 节课，每节 45 分钟 数据：data/07-modeling/BostonHousing.csv 参考脚本：scripts/07-regression/ 下 4 个文件，与正文代码块一一对应。 你将学到：建立第一个线性回归模型，用 MAE、RMSE、R² 评估误差，解释系数方向、相关性与共线性，最..."}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:locale","content":"zh-CN"}]]},"git":{},"autoDesc":true,"filePathRelative":"07-回归模型与业务解释.md"}`),a={name:`07-回归模型与业务解释.md`};function o(e,i,a,o,s,c){return r(),n(`div`,null,[...i[0]||=[t(`<h1 id="week-7-回归模型与业务解释" tabindex="-1"><a class="header-anchor" href="#week-7-回归模型与业务解释"><span>Week 7 回归模型与业务解释</span></a></h1><blockquote><p><strong>本章导读</strong> 时长：3 节课，每节 45 分钟 数据：<code>data/07-modeling/BostonHousing.csv</code> 参考脚本：<code>scripts/07-regression/</code> 下 4 个文件，与正文代码块一一对应。 你将学到：建立第一个线性回归模型，用 MAE、RMSE、R² 评估误差，解释系数方向、相关性与共线性，最后把结果翻译成能上桌的业务结论和不确定项 本周产出：<code>projects/&lt;姓名&gt;/week7_regression.py</code>、<code>projects/&lt;姓名&gt;/week7_regression.md</code></p></blockquote><p>本周三节课：</p><ol><li>第 1 节课：线性回归、训练/测试集与 MAE/RMSE/R²；</li><li>第 2 节课：系数方向、相关性与 Ridge 正则化；</li><li>第 3 节课：业务解释与决策边界。</li></ol><p>本周围绕同一份波士顿房价数据，按固定流程走：</p><pre class="mermaid-raw"><code>flowchart LR
    A[数据：506 行&lt;br/&gt;14 列，目标 medv] --&gt; B[选特征]
    B --&gt; C[切分训练集/测试集]
    C --&gt; D[训练线性回归]
    D --&gt; E[MAE / RMSE / R² 评估]
    E --&gt; F[解释系数与业务边界]</code></pre><p><strong>使用 DSH 的安全规则：先说清目标和验收标准 → 先审 Agent 计划 → 看不懂就解释或暂停 → 执行最小一步 → 检查输出和文件改动 → 保存代码并写结论。</strong> 回归模型不是“算出一个数”，它必须能报出样本量、误差和基线；DSH 说“模型完成”不算完成，必须看到真实指标并能逐项解释。</p><p>回归问题一句话说清：<strong>目标是连续数值，模型给的是估计值，评估看误差。</strong> 本课预测 <code>medv</code>（房价中位数，单位千美元），不是真实成交价，也不代表今天任何具体城市。</p><h2 id="_1-第-1-节课-线性回归、训练-测试集与-mae-rmse-r2-45-分钟" tabindex="-1"><a class="header-anchor" href="#_1-第-1-节课-线性回归、训练-测试集与-mae-rmse-r2-45-分钟"><span>1. 第 1 节课 线性回归、训练/测试集与 MAE/RMSE/R²（45 分钟）</span></a></h2><h3 id="_1-1-节奏" tabindex="-1"><a class="header-anchor" href="#_1-1-节奏"><span>1.1 节奏</span></a></h3><ul><li>演示：读数据 → 切分 → 训练 → 输出 MAE/RMSE/R² 和均值基线。</li><li>练习：按同样步骤跑通，再换特征、改 <code>random_state</code> 观察指标变化。</li><li>复盘：解释三个指标的单位和样本量，完成验收。</li></ul><h3 id="_1-2-数据与问题" tabindex="-1"><a class="header-anchor" href="#_1-2-数据与问题"><span>1.2 数据与问题</span></a></h3><p>数据：<code>data/07-modeling/BostonHousing.csv</code>，506 行、14 列，目标变量是 <code>medv</code>（自住房价中位数，单位千美元）。</p><p>本课用 6 个特征：</p><table><thead><tr><th>字段</th><th>含义</th><th>方向预期</th></tr></thead><tbody><tr><td><code>crim</code></td><td>城镇人均犯罪率</td><td>犯罪率高，房价预期更低</td></tr><tr><td><code>rm</code></td><td>每套住宅平均房间数</td><td>房间多，房价预期更高</td></tr><tr><td><code>lstat</code></td><td>低收入人口比例（%）</td><td>低收入比例高，房价预期更低</td></tr><tr><td><code>ptratio</code></td><td>学生/教师比</td><td>比值高，房价预期更低</td></tr><tr><td><code>nox</code></td><td>一氧化氮浓度</td><td>污染重，房价预期更低</td></tr><tr><td><code>age</code></td><td>1940 年前建成的自住房比例</td><td>房屋旧，房价预期更低</td></tr></tbody></table><p>要回答的问题：<strong>用这 6 个特征估计 <code>medv</code>，平均误差是多少，比“永远猜均值”好多少。</strong></p><p>安全提醒：这是 1970 年代波士顿历史教学数据，<code>medv</code> 是当时的千美元口径，不代表今天的房价、也不代表任何具体城市。<code>data/</code> 只读，本课不修改原数据。</p><h3 id="_1-3-dsh-vibe-loop" tabindex="-1"><a class="header-anchor" href="#_1-3-dsh-vibe-loop"><span>1.3 DSH vibe loop</span></a></h3><p>完整循环：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">定义问题 → 要求最小版本 → 运行 → 反馈 → 追问 → 验证</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>第一版发给 DSH 的提示词只做两件事：读数据、跑一个最小回归。不要让它一次做完解释、调参和报告。</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">请读取 data/07-modeling/BostonHousing.csv，不要修改 data/。</span>
<span class="line">只输出：</span>
<span class="line">1. shape、缺失值、medv 的 describe；</span>
<span class="line">2. 用 crim、rm、lstat、ptratio、nox、age 这 6 个特征预测 medv；</span>
<span class="line">3. train_test_split(test_size=0.2, random_state=42)；</span>
<span class="line">4. 输出训练集/测试集样本量、MAE、RMSE、R²，以及“永远猜测试集均值”的 MAE/RMSE。</span>
<span class="line">先给计划，不要一次写完整份报告，不要安装新依赖。</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行前检查命令：是否写文件、是否改 <code>data/</code>、随机步骤是否固定 <code>random_state=42</code>。执行后核对样本量和指标。<strong>测试集只用于最终评估，不能反过来用于训练。</strong></p><h3 id="_1-4-核心代码" tabindex="-1"><a class="header-anchor" href="#_1-4-核心代码"><span>1.4 核心代码</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> pandas <span class="token keyword">as</span> pd</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> train_test_split</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LinearRegression</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> mean_absolute_error<span class="token punctuation">,</span> mean_squared_error<span class="token punctuation">,</span> r2_score</span>
<span class="line"></span>
<span class="line">df <span class="token operator">=</span> pd<span class="token punctuation">.</span>read_csv<span class="token punctuation">(</span><span class="token string">&#39;data/07-modeling/BostonHousing.csv&#39;</span><span class="token punctuation">)</span></span>
<span class="line">features <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;crim&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;rm&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;lstat&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;nox&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span></span>
<span class="line">X <span class="token operator">=</span> df<span class="token punctuation">[</span>features<span class="token punctuation">]</span></span>
<span class="line">y <span class="token operator">=</span> df<span class="token punctuation">[</span><span class="token string">&#39;medv&#39;</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">X_train<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> y_test <span class="token operator">=</span> train_test_split<span class="token punctuation">(</span></span>
<span class="line">    X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> test_size<span class="token operator">=</span><span class="token number">0.2</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">model <span class="token operator">=</span> LinearRegression<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">model<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">train_pred <span class="token operator">=</span> model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_train<span class="token punctuation">)</span></span>
<span class="line">test_pred <span class="token operator">=</span> model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span></span>
<span class="line">baseline_pred <span class="token operator">=</span> <span class="token punctuation">[</span>y_test<span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token operator">*</span> <span class="token builtin">len</span><span class="token punctuation">(</span>y_test<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;样本量：全量&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>df<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;，训练集&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>X_train<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;，测试集&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;训练集 R2：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r2_score<span class="token punctuation">(</span>y_train<span class="token punctuation">,</span> train_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 R2：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r2_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 MAE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_absolute_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;基线(猜均值) MAE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_absolute_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> baseline_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;基线(猜均值) RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> baseline_pred<span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 medv 均值：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>y_test<span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/07-regression/01-boston-linear.py" target="_blank" rel="noopener noreferrer">01-boston-linear.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/07-modeling/BostonHousing.csv" target="_blank" rel="noopener noreferrer">BostonHousing.csv</a></p><p>运行建模前，先单独读数据并确认 <code>df.shape</code> 是 <code>(506, 14)</code>、缺失值是 <code>0</code>。</p><h3 id="_1-5-实际输出" tabindex="-1"><a class="header-anchor" href="#_1-5-实际输出"><span>1.5 实际输出</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">(506, 14)</span>
<span class="line">0</span>
<span class="line">样本量：全量 506 ，训练集 404 ，测试集 102</span>
<span class="line">训练集 R2： 0.6961</span>
<span class="line">测试集 R2： 0.6226</span>
<span class="line">测试集 MAE： 3.3659</span>
<span class="line">测试集 RMSE： 5.2607</span>
<span class="line">基线(猜均值) MAE： 5.9349</span>
<span class="line">基线(猜均值) RMSE： 8.5635</span>
<span class="line">测试集 medv 均值： 21.4882</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>注意两件事：训练集 404 条、测试集 102 条；模型测试集 MAE 3.37，比“永远猜均值”的 5.93 低，说明这些特征确实带来一些预测能力。</p><h3 id="_1-6-重点解释" tabindex="-1"><a class="header-anchor" href="#_1-6-重点解释"><span>1.6 重点解释</span></a></h3><p>三个指标都要带单位（千美元）和样本量（102 条测试集）解释：</p><table><thead><tr><th>指标</th><th>含义</th><th>本例</th></tr></thead><tbody><tr><td>MAE</td><td>平均绝对误差，每个预测平均差多少</td><td>约 3.37 千美元</td></tr><tr><td>RMSE</td><td>先平方再开方，大误差会被放大</td><td>约 5.26 千美元</td></tr><tr><td>R²</td><td>相对“永远猜均值”的改进比例</td><td>测试集约 0.62</td></tr><tr><td>均值基线</td><td>永远用测试集平均值当预测</td><td>MAE 约 5.93，RMSE 约 8.56</td></tr></tbody></table><p>解释要点：</p><ul><li><strong>MAE 3.37</strong>：测试集 102 条预测平均偏差约 3.37 千美元，是最直观的“平均差多少”。</li><li><strong>RMSE 5.26 大于 MAE 3.37</strong>：说明存在少数误差很大的样本，平方后把它们放大。</li><li><strong>R² 0.62</strong>：约 62% 的房价波动被这 6 个特征解释，还有约 38% 没被解释。R² 不是“准确率”，更不是“62% 的预测正确”。</li><li><strong>基线不能省略</strong>：只报 R² 0.62，别人不知道这个数字好不好。和“永远猜均值”比，MAE 从 5.93 降到 3.37，才说明模型有效。</li><li><strong>为什么先切分</strong>：模型只在 404 条训练集上拟合，102 条测试集模拟“没见过的新数据”。如果先看完全部数据再训练，分数会虚高，这是数据泄漏。</li></ul><p><strong>报告一个回归模型，至少要写：样本量、特征数、训练/测试切分、MAE、RMSE、R² 和一个简单基线。</strong> 只说“R² 0.62”不够。</p><h3 id="_1-7-课堂练习" tabindex="-1"><a class="header-anchor" href="#_1-7-课堂练习"><span>1.7 课堂练习</span></a></h3><ol><li>把特征改成 <code>[&#39;rm&#39;, &#39;lstat&#39;]</code> 重新跑，报告样本量、训练/测试 R²、MAE、RMSE，并和 6 特征版本比较哪一组测试集误差更小。</li><li>解释为什么测试集 R²（0.6226）比训练集 R²（0.6961）低。</li><li>把 <code>random_state=42</code> 改成 <code>random_state=7</code>，观察三个指标是否变化；说明正式报告为什么固定 <code>random_state=42</code>。</li><li>用一句话说明：测试集 MAE 从基线 5.9349 降到模型 3.3659，业务上意味着什么。</li></ol><h3 id="_1-8-第-1-节课验收" tabindex="-1"><a class="header-anchor" href="#_1-8-第-1-节课验收"><span>1.8 第 1 节课验收</span></a></h3><ul><li>[ ] 能说出 <code>medv</code> 是目标变量，数据 506 行、14 列、0 缺失</li><li>[ ] 训练集 404 条、测试集 102 条，<code>random_state=42</code>，先切分再训练</li><li>[ ] 能运行线性回归，输出 MAE、RMSE、R² 和均值基线</li><li>[ ] 能说明 MAE/RMSE 的单位是千美元，R² 不是准确率</li><li>[ ] 能和“永远猜测试集均值”的基线比较，而不是只看单个指标</li><li>[ ] 能写出一句“模型预测不等于真实成交价”</li></ul><h3 id="_1-9-扩展数据练习-mpg-油耗回归" tabindex="-1"><a class="header-anchor" href="#_1-9-扩展数据练习-mpg-油耗回归"><span>1.9 扩展数据练习 mpg 油耗回归</span></a></h3><p>用 <code>data/07-modeling/mpg.csv</code> 换一套数据重复第 1 节流程。目标是 <code>mpg</code>（每加仑英里数），特征包括 <code>horsepower</code>、<code>weight</code>、<code>displacement</code>、<code>model_year</code> 和 <code>origin</code>。<code>origin</code> 是分类字符串，需要先映射成数值。</p><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> pandas <span class="token keyword">as</span> pd</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> train_test_split</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LinearRegression</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> mean_absolute_error<span class="token punctuation">,</span> mean_squared_error<span class="token punctuation">,</span> r2_score</span>
<span class="line"></span>
<span class="line">df <span class="token operator">=</span> pd<span class="token punctuation">.</span>read_csv<span class="token punctuation">(</span><span class="token string">&#39;data/07-modeling/mpg.csv&#39;</span><span class="token punctuation">)</span></span>
<span class="line">df <span class="token operator">=</span> df<span class="token punctuation">.</span>dropna<span class="token punctuation">(</span>subset<span class="token operator">=</span><span class="token punctuation">[</span><span class="token string">&#39;horsepower&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;weight&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;displacement&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;model_year&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;origin&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;mpg&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span></span>
<span class="line">features <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;horsepower&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;weight&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;displacement&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;model_year&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;origin&#39;</span><span class="token punctuation">]</span></span>
<span class="line">X <span class="token operator">=</span> df<span class="token punctuation">[</span>features<span class="token punctuation">]</span><span class="token punctuation">.</span>copy<span class="token punctuation">(</span><span class="token punctuation">)</span></span>
<span class="line">X<span class="token punctuation">[</span><span class="token string">&#39;origin&#39;</span><span class="token punctuation">]</span> <span class="token operator">=</span> X<span class="token punctuation">[</span><span class="token string">&#39;origin&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span><span class="token builtin">map</span><span class="token punctuation">(</span><span class="token punctuation">{</span><span class="token string">&#39;usa&#39;</span><span class="token punctuation">:</span> <span class="token number">0</span><span class="token punctuation">,</span> <span class="token string">&#39;japan&#39;</span><span class="token punctuation">:</span> <span class="token number">1</span><span class="token punctuation">,</span> <span class="token string">&#39;europe&#39;</span><span class="token punctuation">:</span> <span class="token number">2</span><span class="token punctuation">}</span><span class="token punctuation">)</span></span>
<span class="line">y <span class="token operator">=</span> df<span class="token punctuation">[</span><span class="token string">&#39;mpg&#39;</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">X_train<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> y_test <span class="token operator">=</span> train_test_split<span class="token punctuation">(</span></span>
<span class="line">    X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> test_size<span class="token operator">=</span><span class="token number">0.2</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">model <span class="token operator">=</span> LinearRegression<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line">test_pred <span class="token operator">=</span> model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span></span>
<span class="line">baseline_pred <span class="token operator">=</span> <span class="token punctuation">[</span>y_test<span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">]</span> <span class="token operator">*</span> <span class="token builtin">len</span><span class="token punctuation">(</span>y_test<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;样本量：全量&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>df<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;，训练集&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>X_train<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;，测试集&#39;</span><span class="token punctuation">,</span> <span class="token builtin">len</span><span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 MAE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_absolute_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 R2：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r2_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;基线(猜均值) MAE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_absolute_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> baseline_pred<span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;基线(猜均值) RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> baseline_pred<span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/07-regression/04-mpg-regression.py" target="_blank" rel="noopener noreferrer">04-mpg-regression.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/07-modeling/mpg.csv" target="_blank" rel="noopener noreferrer">mpg.csv</a></p><p>实际输出：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">样本量：全量 392 ，训练集 313 ，测试集 79</span>
<span class="line">测试集 MAE： 2.5767</span>
<span class="line">测试集 RMSE： 3.2832</span>
<span class="line">测试集 R2： 0.7888</span>
<span class="line">基线(猜均值) MAE： 5.8176</span>
<span class="line">基线(猜均值) RMSE： 7.1443</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>读法：392 个样本去掉 6 个缺失后进入训练。测试集 79 条，模型 MAE 2.58、RMSE 3.28，明显低于猜均值的 5.82 和 7.14，说明这些特征对油耗有预测价值。</p><p>练习：</p><ol><li>去掉 <code>origin</code> 重跑，报告测试集 R² 和 RMSE 变化，说明产地信息是否带来额外预测能力。</li><li>把 <code>model_year</code> 从数值列改成字符串再跑，观察 sklearn 报错，解释分类变量为什么不能直接进入线性回归。</li><li>用 <code>df[&#39;weight&#39;].corr(df[&#39;mpg&#39;])</code> 和 <code>df[&#39;horsepower&#39;].corr(df[&#39;mpg&#39;])</code> 分别报告两个相关系数，并比较方向。</li></ol><h2 id="_2-第-2-节课-系数方向、相关性与-ridge-正则化-45-分钟" tabindex="-1"><a class="header-anchor" href="#_2-第-2-节课-系数方向、相关性与-ridge-正则化-45-分钟"><span>2. 第 2 节课 系数方向、相关性与 Ridge 正则化（45 分钟）</span></a></h2><h3 id="_2-1-节奏" tabindex="-1"><a class="header-anchor" href="#_2-1-节奏"><span>2.1 节奏</span></a></h3><ul><li>演示：标准化系数、相关系数和 Ridge 对比。</li><li>练习：解释每个特征的方向，尝试不同 <code>alpha</code>，说明符号翻转。</li><li>复盘：相关不等于因果，系数不等于单个特征的贡献。</li></ul><h3 id="_2-2-数据与问题" tabindex="-1"><a class="header-anchor" href="#_2-2-数据与问题"><span>2.2 数据与问题</span></a></h3><p>数据仍是 <code>data/07-modeling/BostonHousing.csv</code>，目标变量 <code>medv</code>。本课回答三个问题：</p><ol><li>哪些特征把估计值往上推、哪些往下推？</li><li>特征之间是否互相相关，会不会干扰系数解释？</li><li>这份数据有没有明显过拟合，Ridge 正则化能带来多少改变？</li></ol><h3 id="_2-3-dsh-vibe-loop" tabindex="-1"><a class="header-anchor" href="#_2-3-dsh-vibe-loop"><span>2.3 DSH vibe loop</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">定义问题 → 要求最小版本 → 运行 → 反馈 → 追问 → 验证</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>发给 DSH 的提示词限定在“解释”而不是“调参”：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">沿用 data/07-modeling/BostonHousing.csv，特征 crim、rm、lstat、ptratio、nox、age，</span>
<span class="line">目标 medv，train_test_split(test_size=0.2, random_state=42)。</span>
<span class="line">不要调参。请输出：</span>
<span class="line">1. StandardScaler + LinearRegression 的标准化系数，按绝对值从大到小排；</span>
<span class="line">2. 每个特征与 medv 的相关系数；</span>
<span class="line">3. rm 与 lstat、nox 与 age 的相关系数；</span>
<span class="line">4. LinearRegression 与 Ridge(alpha=1.0) 在测试集上的 R² 和 RMSE。</span>
<span class="line">逐项解释方向和共线性，不要给因果结论。</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>执行前检查：是否有 <code>StandardScaler</code> 泄漏（必须放在 <code>make_pipeline</code> 里或拆分后只用训练集 fit）、是否只用了 pandas 和 scikit-learn。</p><h3 id="_2-4-核心代码" tabindex="-1"><a class="header-anchor" href="#_2-4-核心代码"><span>2.4 核心代码</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> pandas <span class="token keyword">as</span> pd</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> train_test_split</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LinearRegression<span class="token punctuation">,</span> Ridge</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>preprocessing <span class="token keyword">import</span> StandardScaler</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>pipeline <span class="token keyword">import</span> make_pipeline</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> mean_squared_error<span class="token punctuation">,</span> r2_score</span>
<span class="line"></span>
<span class="line">df <span class="token operator">=</span> pd<span class="token punctuation">.</span>read_csv<span class="token punctuation">(</span><span class="token string">&#39;data/07-modeling/BostonHousing.csv&#39;</span><span class="token punctuation">)</span></span>
<span class="line">features <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;crim&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;rm&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;lstat&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;nox&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span></span>
<span class="line">X <span class="token operator">=</span> df<span class="token punctuation">[</span>features<span class="token punctuation">]</span></span>
<span class="line">y <span class="token operator">=</span> df<span class="token punctuation">[</span><span class="token string">&#39;medv&#39;</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">X_train<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> y_test <span class="token operator">=</span> train_test_split<span class="token punctuation">(</span></span>
<span class="line">    X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> test_size<span class="token operator">=</span><span class="token number">0.2</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 系数方向：先标准化，让不同量纲的系数可以比较大小</span></span>
<span class="line">pipe <span class="token operator">=</span> make_pipeline<span class="token punctuation">(</span>StandardScaler<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> LinearRegression<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line">pipe<span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line">coef <span class="token operator">=</span> pipe<span class="token punctuation">.</span>named_steps<span class="token punctuation">[</span><span class="token string">&#39;linearregression&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>coef_</span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;标准化后的系数（按绝对值从大到小）：&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> name<span class="token punctuation">,</span> c <span class="token keyword">in</span> <span class="token builtin">sorted</span><span class="token punctuation">(</span><span class="token builtin">zip</span><span class="token punctuation">(</span>features<span class="token punctuation">,</span> coef<span class="token punctuation">)</span><span class="token punctuation">,</span> key<span class="token operator">=</span><span class="token keyword">lambda</span> t<span class="token punctuation">:</span> <span class="token operator">-</span><span class="token builtin">abs</span><span class="token punctuation">(</span>t<span class="token punctuation">[</span><span class="token number">1</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> name<span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>c<span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;各特征与 medv 的相关系数：&#39;</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">for</span> name <span class="token keyword">in</span> features<span class="token punctuation">:</span></span>
<span class="line">    <span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39; &#39;</span><span class="token punctuation">,</span> name<span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>df<span class="token punctuation">[</span>name<span class="token punctuation">]</span><span class="token punctuation">.</span>corr<span class="token punctuation">(</span>df<span class="token punctuation">[</span><span class="token string">&#39;medv&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;rm 与 lstat 相关系数：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>df<span class="token punctuation">[</span><span class="token string">&#39;rm&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>corr<span class="token punctuation">(</span>df<span class="token punctuation">[</span><span class="token string">&#39;lstat&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;nox 与 age 相关系数：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>df<span class="token punctuation">[</span><span class="token string">&#39;nox&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>corr<span class="token punctuation">(</span>df<span class="token punctuation">[</span><span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># Ridge 正则化对比</span></span>
<span class="line">lin <span class="token operator">=</span> LinearRegression<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line">ridge <span class="token operator">=</span> make_pipeline<span class="token punctuation">(</span>StandardScaler<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> Ridge<span class="token punctuation">(</span>alpha<span class="token operator">=</span><span class="token number">1.0</span><span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;线性回归 测试 R2：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r2_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> lin<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;Ridge    测试 R2：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>r2_score<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> ridge<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;线性回归 测试 RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> lin<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;Ridge    测试 RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> ridge<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span><span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/07-regression/02-boston-coefficients.py" target="_blank" rel="noopener noreferrer">02-boston-coefficients.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/07-modeling/BostonHousing.csv" target="_blank" rel="noopener noreferrer">BostonHousing.csv</a></p><h3 id="_2-5-实际输出" tabindex="-1"><a class="header-anchor" href="#_2-5-实际输出"><span>2.5 实际输出</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">标准化后的系数（按绝对值从大到小）：</span>
<span class="line">  lstat -3.9774</span>
<span class="line">  rm 3.4184</span>
<span class="line">  ptratio -1.8905</span>
<span class="line">  age 0.9266</span>
<span class="line">  crim -0.7551</span>
<span class="line">  nox -0.5523</span>
<span class="line">各特征与 medv 的相关系数：</span>
<span class="line">  crim -0.3883</span>
<span class="line">  rm 0.6954</span>
<span class="line">  lstat -0.7377</span>
<span class="line">  ptratio -0.5078</span>
<span class="line">  nox -0.4273</span>
<span class="line">  age -0.377</span>
<span class="line">rm 与 lstat 相关系数： -0.6138</span>
<span class="line">nox 与 age 相关系数： 0.7315</span>
<span class="line">线性回归 测试 R2： 0.6226</span>
<span class="line">Ridge    测试 R2： 0.6228</span>
<span class="line">线性回归 测试 RMSE： 5.2607</span>
<span class="line">Ridge    测试 RMSE： 5.2593</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_2-6-重点解释" tabindex="-1"><a class="header-anchor" href="#_2-6-重点解释"><span>2.6 重点解释</span></a></h3><ul><li><strong>标准化系数用来比较相对大小。</strong> 原始特征量纲差别很大（<code>crim</code> 约 0-88，<code>rm</code> 约 3-9，<code>nox</code> 约 0.38-0.87），原始系数不能直接比大小；标准化后系数越大，说明该特征在模型里的影响越强。本例 <code>lstat</code>（-3.9774）和 <code>rm</code>（+3.4184）影响最大。</li><li><strong>方向要对照业务预期。</strong> <code>rm</code> 为正、<code>lstat</code> 为负、<code>ptratio</code> 为负、<code>crim</code> 为负、<code>nox</code> 为负，都和直觉一致；<code>rm</code> 原始系数约 +4.82，意思是“其他条件不变时，平均房间数每多 1 间，估计房价中位数约高 4.82 千美元”。</li><li><strong>相关系数和系数不是一回事。</strong> 相关系数是“只看这一个特征”，系数是“控制其他特征后看这一个特征”。<code>age</code> 与 <code>medv</code> 的相关系数是 -0.377，但标准化系数是 +0.9266，符号相反；原因是 <code>age</code> 与 <code>nox</code> 高度相关（0.7315），多元模型里符号被共线性翻转。<strong>不能拿单变量相关性的方向代替多元系数。</strong></li><li><strong>共线性会让解释变脆。</strong> <code>rm</code> 与 <code>lstat</code> 相关 -0.6138，<code>nox</code> 与 <code>age</code> 相关 0.7315，特征不是互相独立，所以“单独加一间房一定涨 4.82 千美元”这类话要谨慎，它依赖“其他特征不变”这个假设。</li><li><strong>Ridge 在本数据几乎不改变结果。</strong> 线性回归测试 R² 0.6226、RMSE 5.2607；Ridge(alpha=1.0) 测试 R² 0.6228、RMSE 5.2593。差值是小数点后第三位，说明 6 个特征、404 条训练样本下没有明显过拟合。<strong>正则化不是“一键变好”的开关；只有当特征很多、共线性很强或样本很少时，它才更可能发挥作用。</strong></li></ul><h3 id="_2-7-课堂练习" tabindex="-1"><a class="header-anchor" href="#_2-7-课堂练习"><span>2.7 课堂练习</span></a></h3><ol><li>用原始系数解释 <code>rm</code> 和 <code>lstat</code> 的方向，并说明为什么比较大小前要先标准化。</li><li>解释 <code>age</code> 的相关系数为负（-0.377）但标准化系数为正（+0.9266），指出可能的共线性来源。</li><li>把 Ridge 的 <code>alpha</code> 改成 <code>0.01</code> 和 <code>10</code>，比较测试 R²/RMSE，写一句“这份数据里正则化改变大不大”。</li><li>判断下面这句话错在哪：“<code>rm</code> 与 <code>medv</code> 相关系数 0.6954，所以房间数增加一定会让房价上涨。”</li></ol><h3 id="_2-8-第-2-节课验收" tabindex="-1"><a class="header-anchor" href="#_2-8-第-2-节课验收"><span>2.8 第 2 节课验收</span></a></h3><ul><li>[ ] 能输出标准化系数并解释每个特征的符号方向</li><li>[ ] 能说清相关系数和多元系数的区别</li><li>[ ] 能解释 <code>age</code> 相关系数为负但系数为正的共线性原因</li><li>[ ] 能指出 <code>rm</code> 与 <code>lstat</code>、<code>nox</code> 与 <code>age</code> 的相关强度</li><li>[ ] 能运行 Ridge 对比，并说明本数据中正则化几乎不改变结果</li><li>[ ] 不把系数直接说成因果关系</li></ul><h2 id="_3-第-3-节课-业务解释与决策边界-45-分钟" tabindex="-1"><a class="header-anchor" href="#_3-第-3-节课-业务解释与决策边界-45-分钟"><span>3. 第 3 节课 业务解释与决策边界（45 分钟）</span></a></h2><h3 id="_3-1-节奏" tabindex="-1"><a class="header-anchor" href="#_3-1-节奏"><span>3.1 节奏</span></a></h3><ul><li>演示：两个具体样本的预测，并写成带 RMSE 的结论。</li><li>练习：写“能支持什么、不能支持什么”，列出不确定项，互查结论。</li><li>复盘：“估计值 + 误差区间”和“因果结论”的边界。</li></ul><h3 id="_3-2-数据与问题" tabindex="-1"><a class="header-anchor" href="#_3-2-数据与问题"><span>3.2 数据与问题</span></a></h3><p>数据仍是 <code>data/07-modeling/BostonHousing.csv</code>。本课不再换模型，回答业务问题：</p><p><strong>如果有人说“这个模型能预测波士顿房价”，它到底能支持什么决策、不能支持什么决策？</strong></p><h3 id="_3-3-dsh-vibe-loop" tabindex="-1"><a class="header-anchor" href="#_3-3-dsh-vibe-loop"><span>3.3 DSH vibe loop</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">定义问题 → 要求最小版本 → 运行 → 反馈 → 追问 → 验证</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>让 DSH 先给出“解释草稿”，再让学生审查，而不是让它替学生下结论：</p><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">沿用前面的波士顿房价线性回归（6 个特征，random_state=42）。</span>
<span class="line">请基于测试集 RMSE 约 5.26 千美元、样本量 102 条，写一段结论草稿，要求：</span>
<span class="line">1. 明确“估计值”和“真实成交价”的区别；</span>
<span class="line">2. 写出模型能支持什么、不能支持什么；</span>
<span class="line">3. 列出至少 3 个不确定项。</span>
<span class="line">不要给因果结论，不要超出数据范围外推。</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>学生收到草稿后，逐句检查：每一句是否带样本量、指标、单位；有没有把估计写成事实；有没有偷偷变成因果结论。</p><h3 id="_3-4-核心代码" tabindex="-1"><a class="header-anchor" href="#_3-4-核心代码"><span>3.4 核心代码</span></a></h3><div class="language-python line-numbers-mode" data-highlighter="prismjs" data-ext="py"><pre><code class="language-python"><span class="line"><span class="token keyword">import</span> pandas <span class="token keyword">as</span> pd</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>model_selection <span class="token keyword">import</span> train_test_split</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>linear_model <span class="token keyword">import</span> LinearRegression</span>
<span class="line"><span class="token keyword">from</span> sklearn<span class="token punctuation">.</span>metrics <span class="token keyword">import</span> mean_squared_error</span>
<span class="line"></span>
<span class="line">df <span class="token operator">=</span> pd<span class="token punctuation">.</span>read_csv<span class="token punctuation">(</span><span class="token string">&#39;data/07-modeling/BostonHousing.csv&#39;</span><span class="token punctuation">)</span></span>
<span class="line">features <span class="token operator">=</span> <span class="token punctuation">[</span><span class="token string">&#39;crim&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;rm&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;lstat&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;nox&#39;</span><span class="token punctuation">,</span> <span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span></span>
<span class="line">X <span class="token operator">=</span> df<span class="token punctuation">[</span>features<span class="token punctuation">]</span></span>
<span class="line">y <span class="token operator">=</span> df<span class="token punctuation">[</span><span class="token string">&#39;medv&#39;</span><span class="token punctuation">]</span></span>
<span class="line"></span>
<span class="line">X_train<span class="token punctuation">,</span> X_test<span class="token punctuation">,</span> y_train<span class="token punctuation">,</span> y_test <span class="token operator">=</span> train_test_split<span class="token punctuation">(</span></span>
<span class="line">    X<span class="token punctuation">,</span> y<span class="token punctuation">,</span> test_size<span class="token operator">=</span><span class="token number">0.2</span><span class="token punctuation">,</span> random_state<span class="token operator">=</span><span class="token number">42</span></span>
<span class="line"><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line">model <span class="token operator">=</span> LinearRegression<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>fit<span class="token punctuation">(</span>X_train<span class="token punctuation">,</span> y_train<span class="token punctuation">)</span></span>
<span class="line">test_pred <span class="token operator">=</span> model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>X_test<span class="token punctuation">)</span></span>
<span class="line">rmse <span class="token operator">=</span> mean_squared_error<span class="token punctuation">(</span>y_test<span class="token punctuation">,</span> test_pred<span class="token punctuation">)</span> <span class="token operator">**</span> <span class="token number">0.5</span></span>
<span class="line">resid <span class="token operator">=</span> y_test <span class="token operator">-</span> test_pred</span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;测试集 RMSE：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>rmse<span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;绝对误差中位数：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>resid<span class="token punctuation">.</span><span class="token builtin">abs</span><span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;误差在 ±5 千美元内：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span><span class="token punctuation">(</span>resid<span class="token punctuation">.</span><span class="token builtin">abs</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">5</span><span class="token punctuation">)</span><span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;误差在 ±10 千美元内：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span><span class="token punctuation">(</span>resid<span class="token punctuation">.</span><span class="token builtin">abs</span><span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token operator">&lt;=</span> <span class="token number">10</span><span class="token punctuation">)</span><span class="token punctuation">.</span>mean<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token comment"># 其他字段取全量中位数，只看 rm 和 lstat 变化</span></span>
<span class="line">row_a <span class="token operator">=</span> pd<span class="token punctuation">.</span>DataFrame<span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token string">&#39;crim&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;crim&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;rm&#39;</span><span class="token punctuation">:</span> <span class="token number">6.0</span><span class="token punctuation">,</span> <span class="token string">&#39;lstat&#39;</span><span class="token punctuation">:</span> <span class="token number">12.0</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;nox&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;nox&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&#39;age&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span> columns<span class="token operator">=</span>features<span class="token punctuation">)</span></span>
<span class="line">row_b <span class="token operator">=</span> pd<span class="token punctuation">.</span>DataFrame<span class="token punctuation">(</span><span class="token punctuation">[</span><span class="token punctuation">{</span></span>
<span class="line">    <span class="token string">&#39;crim&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;crim&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;rm&#39;</span><span class="token punctuation">:</span> <span class="token number">7.0</span><span class="token punctuation">,</span> <span class="token string">&#39;lstat&#39;</span><span class="token punctuation">:</span> <span class="token number">5.0</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;ptratio&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span> <span class="token string">&#39;nox&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;nox&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line">    <span class="token string">&#39;age&#39;</span><span class="token punctuation">:</span> df<span class="token punctuation">[</span><span class="token string">&#39;age&#39;</span><span class="token punctuation">]</span><span class="token punctuation">.</span>median<span class="token punctuation">(</span><span class="token punctuation">)</span><span class="token punctuation">,</span></span>
<span class="line"><span class="token punctuation">}</span><span class="token punctuation">]</span><span class="token punctuation">,</span> columns<span class="token operator">=</span>features<span class="token punctuation">)</span></span>
<span class="line"></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;rm=6、lstat=12 的估计：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>row_a<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"><span class="token keyword">print</span><span class="token punctuation">(</span><span class="token string">&#39;rm=7、lstat=5 的估计：&#39;</span><span class="token punctuation">,</span> <span class="token builtin">round</span><span class="token punctuation">(</span>model<span class="token punctuation">.</span>predict<span class="token punctuation">(</span>row_b<span class="token punctuation">)</span><span class="token punctuation">[</span><span class="token number">0</span><span class="token punctuation">]</span><span class="token punctuation">,</span> <span class="token number">4</span><span class="token punctuation">)</span><span class="token punctuation">)</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><p>脚本：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/scripts/07-regression/03-boston-business-error.py" target="_blank" rel="noopener noreferrer">03-boston-business-error.py</a> ｜ 数据：<a href="https://github.com/zhouxzh/personal-site/blob/main/course-materials/python-data-analysis/data/07-modeling/BostonHousing.csv" target="_blank" rel="noopener noreferrer">BostonHousing.csv</a></p><h3 id="_3-5-实际输出" tabindex="-1"><a class="header-anchor" href="#_3-5-实际输出"><span>3.5 实际输出</span></a></h3><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">测试集 RMSE： 5.2607</span>
<span class="line">绝对误差中位数： 2.275</span>
<span class="line">误差在 ±5 千美元内： 0.8137</span>
<span class="line">误差在 ±10 千美元内： 0.9314</span>
<span class="line">rm=6、lstat=12 的估计： 21.5761</span>
<span class="line">rm=7、lstat=5 的估计： 30.3209</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-6-重点解释" tabindex="-1"><a class="header-anchor" href="#_3-6-重点解释"><span>3.6 重点解释</span></a></h3><ul><li><strong>单个预测是估计值，不是成交价。</strong> <code>rm=6、lstat=12</code> 的估计约 21.58 千美元，<code>rm=7、lstat=5</code> 的估计约 30.32 千美元。测试集 RMSE 约 5.26 千美元，意味着典型误差在这个量级；本数据中 81.37% 的测试误差落在 ±5 千美元内，93.14% 落在 ±10 千美元内。结论应写成“估计约 30.32 千美元，测试集 RMSE 约 5.26 千美元”，而不是“这套房值 30.32 千美元”。</li><li><strong>模型能支持什么：</strong> 在相同特征口径下比较相对高低（例如房间多、低收入比例低的样本估计更高），发现哪些特征与 <code>medv</code> 关联更强，作为进一步调查或筛选的线索。</li><li><strong>模型不能支持什么：</strong> 不能证明因果（不能说“加一间房导致房价涨”），不能外推到数据范围之外（例如把 <code>rm</code> 设成 20），不能给出单个成交价的保证，不能预测未来市场。</li><li><strong>决策边界在于“连续估计 + 误差”。</strong> 回归输出的是一个带误差的数值，不是“值不值”的是/否判断。要做“是否入手”这类决策，还需要阈值、业务代价和更多现场信息；模型只能提供估计和误差，不能替人做决定。</li><li><strong>结论模板：</strong></li></ul><div class="language-text line-numbers-mode" data-highlighter="prismjs" data-ext="text"><pre><code class="language-text"><span class="line">在当前数据、当前特征、当前切分下，模型测试集 RMSE 约 5.26 千美元，样本 102 条。</span>
<span class="line">它能支持：比较不同特征组合的相对高低，作为进一步核查的线索。</span>
<span class="line">它不能支持：证明因果、给出精确成交价、预测未来市场。</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div><div class="line-number"></div><div class="line-number"></div></div></div><h3 id="_3-7-课堂练习" tabindex="-1"><a class="header-anchor" href="#_3-7-课堂练习"><span>3.7 课堂练习</span></a></h3><ol><li>用模型预测 <code>rm=5、lstat=20</code>（其他字段取中位数），写出带 RMSE 的一句结论。参考估计约 12.27 千美元。</li><li>写一段不超过 100 字的结论，必须包含：样本量、测试集 RMSE、能支持什么、不能支持什么。</li><li>列出至少 2 个不确定项，例如：数据是 1970 年代历史口径、样本只覆盖波士顿、因果无法证明、特征存在共线性。</li><li>判断这句话为什么不能写成事实：“把 <code>rm</code> 从 6 加到 7 且 <code>lstat</code> 从 12 降到 5，估计从 21.58 升到 30.32，说明改造房子能涨 8.7 千美元。”</li></ol><h3 id="_3-8-第-3-节课验收" tabindex="-1"><a class="header-anchor" href="#_3-8-第-3-节课验收"><span>3.8 第 3 节课验收</span></a></h3><ul><li>[ ] 能把单点预测写成“估计值 + RMSE”，不写成精确成交价</li><li>[ ] 能说出误差在 ±5 千美元、±10 千美元内的比例及样本量</li><li>[ ] 能写出模型能支持什么、不能支持什么</li><li>[ ] 能区分“相关/关联”和“因果”</li><li>[ ] 结论中列出至少 2 个不确定项</li><li>[ ] 不把连续估计硬说成“是/否”的业务决定</li></ul><h2 id="_4-本周验证清单" tabindex="-1"><a class="header-anchor" href="#_4-本周验证清单"><span>4. 本周验证清单</span></a></h2><ul><li>[ ] 三节课验收全部通过</li><li>[ ] <code>data/</code> 只读，原始数据未被修改</li><li>[ ] 学生代码写入 <code>projects/&lt;姓名&gt;/</code>，路径使用 <code>data/07-modeling/...</code></li><li>[ ] 所有建模代码设置 <code>random_state=42</code>，先切分训练/测试集再训练</li><li>[ ] 回归指标同时包含 MAE、RMSE、R² 和均值基线，并说明样本量</li><li>[ ] 能解释标准化系数的方向，指出 <code>age</code> 的符号翻转来自共线性</li><li>[ ] Ridge 对比能说明本数据中正则化几乎不改变结果</li><li>[ ] 结论区分“估计值”和“事实”，写清不确定项</li><li>[ ] 每次 DSH 都走完 <code>定义问题 → 要求最小版本 → 运行 → 反馈 → 追问 → 验证</code></li><li>[ ] DSH 生成的建模代码能逐行解释每个指标，解释不出来就不算完成</li></ul><h2 id="_5-常见错误与坑" tabindex="-1"><a class="header-anchor" href="#_5-常见错误与坑"><span>5. 常见错误与坑</span></a></h2><table><thead><tr><th>现象</th><th>原因</th><th>处理</th></tr></thead><tbody><tr><td>用测试集反复试模型</td><td>测试集被“训练”了</td><td>最终指标只做一次，诊断用训练集或重新切分</td></tr><tr><td>不设 <code>random_state</code></td><td>每次切分结果不同</td><td>所有随机步骤都固定 <code>random_state=42</code></td></tr><tr><td>先标准化再切分</td><td>测试集信息进入训练过程</td><td>先切分；或把 <code>StandardScaler</code> 放进 <code>make_pipeline</code></td></tr><tr><td>把 R² 当成准确率</td><td>混淆回归和分类指标</td><td>R² 是解释力，MAE/RMSE 才是误差</td></tr><tr><td>只报 R² 不报误差</td><td>业务不知道实际差多少</td><td>加 MAE、RMSE、单位和基线</td></tr><tr><td>把 MAE 当成每一套房都差这么多</td><td>MAE 是平均误差</td><td>结合 RMSE 和测试集误差分布看</td></tr><tr><td>用相关系数代替系数下结论</td><td>忽略其他特征的影响</td><td>同时看相关系数和标准化系数</td></tr><tr><td>把系数直接说成因果</td><td>相关不等于因果</td><td>写成“与……相关联”，并写清限制</td></tr><tr><td>把单点预测说成精确成交价</td><td>忽略模型误差</td><td>写成“估计值 + RMSE”，给出误差范围</td></tr><tr><td>把结果外推到数据范围之外</td><td>模型只在训练数据范围内有效</td><td>检查特征是否落在原数据区间内</td></tr><tr><td>认为 Ridge 一定让模型变好</td><td>正则化不是万能开关</td><td>用测试集指标比较，本数据几乎不变</td></tr><tr><td>DSH 说“完成”就相信</td><td>没有验证代码和输出</td><td>要求逐行解释，并亲自核对运行结果</td></tr></tbody></table><h2 id="_6-作业" tabindex="-1"><a class="header-anchor" href="#_6-作业"><span>6. 作业</span></a></h2><ol><li>把三节课的代码整理成 <code>projects/&lt;姓名&gt;/week7_regression.py</code>。要求：路径写 <code>data/07-modeling/BostonHousing.csv</code>；固定 <code>random_state=42</code>；先切分再训练；输出 MAE、RMSE、R² 和均值基线，并打印样本量。</li><li>写 <code>projects/&lt;姓名&gt;/week7_regression.md</code>，用中文解释：目标变量、6 个特征、训练/测试样本量、MAE/RMSE/R²、均值基线，以及每个标准化系数的方向。</li><li>写不超过 100 字：这个回归模型“能支持什么决策、不能支持什么决策”，并给出 1 个可执行的业务建议和至少 1 个数据限制。</li><li>让 DSH 审查 <code>week7_regression.py</code>，重点检查：是否有数据泄漏、是否只用了 pandas 和 scikit-learn、是否把预测写成事实。保留 DSH 的修改记录。</li></ol><h2 id="评分要点" tabindex="-1"><a class="header-anchor" href="#评分要点"><span>评分要点</span></a></h2><table><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>数据理解</td><td>能指出 <code>medv</code> 是目标变量、数据 506 行 14 列、6 个特征的含义</td></tr><tr><td>数据拆分</td><td>先切分、固定 <code>random_state=42</code>，训练 404 条、测试 102 条</td></tr><tr><td>回归评估</td><td>能解释 MAE、RMSE、R²，并与“永远猜均值”基线比较</td></tr><tr><td>特征解释</td><td>能说明系数方向、标准化意义和 <code>age</code> 的共线性符号翻转</td></tr><tr><td>正则化</td><td>能运行 Ridge 对比，并说明本数据中改变很小</td></tr><tr><td>业务边界</td><td>能区分估计值与事实、相关与因果，写清不确定项</td></tr><tr><td>防泄漏</td><td>标准化放在拆分后或 Pipeline 里，测试集只用于评估</td></tr><tr><td>表达</td><td>结论带样本量、单位和误差，不把模型说成因果或保证</td></tr></tbody></table>`,102)]])}var s=e(a,[[`render`,o]]);export{i as _pageData,s as default};